package com.josephmarchand.englishjoe.courses;

import com.josephmarchand.englishjoe.models.Question;
import java.util.List;

/** Quiz items for the second set of lessons (IDs 31–60). */
public final class LessonQuizExtension {
    private LessonQuizExtension() {}

    public static void addQuestions(int id, List<Question> out) {
        switch (id) {
            case 31: pair(out,"How do you ask someone's age?", "How old are you?","How many years have you?","How age you are?","How old you?",0,"How old are you? est la question naturelle pour demander l'âge."); pair(out,"Complete: I ___ Congolese.", "am","is","are","be",0,"Avec I, on utilise am."); break;
            case 32: pair(out,"My parents ___ kind.", "is","are","am","be",1,"Parents est pluriel : are."); pair(out,"What does cousin mean?", "A parent","A cousin","A teacher","A neighbour",1,"Cousin signifie cousin ou cousine."); break;
            case 33: pair(out,"She ___ up at six every day.", "wake","wakes","waking","is wake",1,"Au présent simple, he/she/it prend généralement -s."); pair(out,"Choose the correct question.", "Does he work?","Do he works?","Does he works?","Is he work?",0,"Après does, le verbe principal reste à la base : work."); break;
            case 34: pair(out,"___ a book on the table.", "There are","There is","They is","There be",1,"There is s'utilise avec un nom singulier."); pair(out,"___ there any chairs?", "Is","Are","Am","Be",1,"Avec le pluriel chairs, on demande Are there…?"); break;
            case 35: pair(out,"He ___ swim very well.", "can","cans","is can","can to",0,"Can est suivi de la base verbale et ne prend pas -s."); pair(out,"Choose a polite permission question.", "Can I come in?","I can come in?","Do I can come in?","Can come I in?",0,"Can I…? est une structure correcte pour demander la permission."); break;
            case 36: pair(out,"Which noun is usually uncountable?", "chair","apple","information","book",2,"Information est généralement indénombrable en anglais."); pair(out,"Choose the correct phrase.", "an advice","some advice","many advice","advices",1,"On dit some advice ou a piece of advice."); break;
            case 37: pair(out,"Choose the natural word order.", "I often read.","I read often always.","Often I am read.","I do often reads.",0,"L'adverbe de fréquence se place souvent avant le verbe principal."); pair(out,"She is ___ late.", "usually","usual","use","usualy",0,"Avec be, l'adverbe de fréquence vient généralement après be."); break;
            case 38: pair(out,"You ___ wear a seat belt. It is the law.", "must","might to","should to","must to",0,"Must est suivi directement de la base verbale."); pair(out,"You ___ smoke here; it is forbidden.", "don't have to","mustn't","shouldn't to","haven't to",1,"Mustn't exprime une interdiction, tandis que don't have to exprime l'absence d'obligation."); break;
            case 39: pair(out,"They ___ football right now.", "play","plays","are playing","played",2,"Une action en cours utilise be + verbe-ing."); pair(out,"Choose the correct question.", "What you are doing?","What are you doing?","What do you doing?","What are doing you?",1,"Dans une question au présent continu : question word + be + sujet + -ing."); break;
            case 40: pair(out,"How do I get ___ the station?", "to","at","on","for",0,"Get to signifie arriver à / se rendre à un lieu."); pair(out,"Turn left means:", "Tourne à droite","Continue tout droit","Tourne à gauche","Arrête-toi",2,"Turn left signifie tourner à gauche."); break;
            case 41: pair(out,"I ___ her yesterday.", "have seen","saw","has seen","see",1,"Yesterday indique un moment passé terminé : past simple."); pair(out,"Have you ever ___ sushi?", "eat","ate","eaten","eating",2,"Après have, on utilise le participe passé : eaten."); break;
            case 42: pair(out,"The woman ___ called is my aunt.", "who","where","when","what",0,"Who sert à introduire une relative concernant une personne."); pair(out,"Which sentence is correct?", "The book who I bought","The book that I bought","The book where I bought","The book what I bought",1,"That peut introduire une relative définissante portant sur une chose."); break;
            case 43: pair(out,"Choose a phrase for partial agreement.", "I partly agree.","You are foolish.","I refuse to listen.","That is irrelevant.",0,"I partly agree exprime un accord partiel."); pair(out,"A respectful disagreement should include a reason and a ___ tone.", "hostile","personal","constructive","mocking",2,"Un ton constructif permet de désapprouver sans attaquer la personne."); break;
            case 44: pair(out,"What does 'give up' mean?", "Continue","Abandonner","Découvrir","S'occuper de",1,"Give up signifie abandonner."); pair(out,"We ran ___ milk.", "out of","after","up","over",0,"Run out of signifie manquer de quelque chose."); break;
            case 45: pair(out,"A topic sentence usually states the paragraph's ___.", "main idea","final punctuation","author's age","page number",0,"La phrase thématique annonce l'idée principale."); pair(out,"Which detail best supports a claim about reading?", "A relevant example","An unrelated joke","A random number","A repeated title",0,"Un exemple pertinent soutient l'idée principale."); break;
            case 46: pair(out,"If I had left earlier, I ___ the bus.", "would catch","would have caught","will catch","caught",1,"Third conditional : if + past perfect, would have + participe passé."); pair(out,"Choose the correct if-clause.", "If I would have known","If I had known","If I have knew","If I had know",1,"La proposition avec if utilise had + participe passé."); break;
            case 47: pair(out,"The lights are on. They ___ be home.", "must","mustn't","can't to","have",0,"Must exprime ici une déduction forte fondée sur un indice."); pair(out,"She ___ be at work; her car is not there, but we are not sure.", "might","mustn't to","has","does",0,"Might exprime une possibilité, pas une certitude."); break;
            case 48: pair(out,"___ the weather was bad, the match continued.", "Although","Because of","Therefore","Despite of",0,"Although introduit une proposition de concession."); pair(out,"The deadline was short; ___, we prioritised key tasks.", "because","therefore","although","whereas",1,"Therefore introduit une conséquence."); break;
            case 49: pair(out,"In an interview, a strong answer should include ___.", "a concrete example","only vague claims","personal attacks","unrelated details",0,"Un exemple concret rend la compétence plus crédible."); pair(out,"What does 'strengths' mean in a job interview?", "Faiblesses","Qualités ou points forts","Horaires","Salaire",1,"Strengths signifie points forts ou qualités."); break;
            case 50: pair(out,"Before choosing a solution, compare its benefits and ___.", "drawbacks","greetings","spelling","accents",0,"Comparer avantages et inconvénients aide à justifier une décision."); pair(out,"Which phrase makes a recommendation?", "I would recommend option B because…","I have no idea ever.","This is not a topic.","Stop talking now.",0,"I would recommend… présente une recommandation et sa justification."); break;
            case 51: pair(out,"If I had studied medicine, I ___ a doctor now.", "would be","will be","would have been yesterday","am",0,"Condition passée et résultat présent : mixed conditional avec would be."); pair(out,"If she were more careful, she ___ that mistake yesterday.", "wouldn't make","wouldn't have made","won't make","didn't made",1,"État présent hypothétique et conséquence passée : would have + participe passé."); break;
            case 52: pair(out,"Which phrase uses nominalisation?", "The committee decided.","The committee's decision was announced.","They decide quickly.","She is deciding.",1,"Decision transforme l'action decide en nom."); pair(out,"Nominalisation can make formal writing more concise, but too much may make it ___.", "clearer in every case","heavy and difficult to read","grammatically impossible","informal only",1,"L'excès de noms abstraits peut alourdir la phrase."); break;
            case 53: pair(out,"The team tested a method. ___ approach reduced errors.", "This","These","Those","Them",0,"This approach reprend clairement le nom singulier method."); pair(out,"A vague 'this' can make a paragraph ___.", "ambiguous","more precise automatically","shorter without risk","grammatically perfect",0,"Il faut préciser ce que this reprend pour éviter l'ambiguïté."); break;
            case 54: pair(out,"A correlation alone does not prove ___.", "causation","a spelling rule","a paragraph","a quotation",0,"Une corrélation ne démontre pas à elle seule un lien causal."); pair(out,"A cautious research conclusion might say:", "The data may suggest…","This proves everything forever.","No other explanation exists.","The result is certain without evidence.",0,"May suggest adapte la conclusion à la force limitée des données."); break;
            case 55: pair(out,"Choose a diplomatic reservation.", "I appreciate the proposal; my concern is the timing.","Your idea is stupid.","I won't listen.","You clearly know nothing.",0,"La formule reconnaît la proposition puis précise la réserve sans attaque personnelle."); pair(out,"Diplomatic disagreement should focus on the ___, not insult the person.", "issue","appearance","family","accent",0,"Le désaccord porte sur le problème ou l'idée, pas sur la personne."); break;
            case 56: pair(out,"“It's getting late” may indirectly suggest that someone should ___.", "consider leaving","buy a clock","change the weather","stop speaking English",0,"Selon le contexte, l'énoncé peut être une invitation implicite à partir."); pair(out,"A pragmatic interpretation should use words and ___.", "context","font size","alphabet order","word length only",0,"Le contexte et la relation entre interlocuteurs aident à interpréter l'intention."); break;
            case 57: pair(out,"“Time is a thief” is an example of ___.", "metaphor","literal measurement","a question tag","a passive sentence",0,"La métaphore représente le temps comme un voleur."); pair(out,"When analysing an image, identify the concrete image and the ___ idea it represents.", "abstract","alphabetical","unrelated","numerical only",0,"Une métaphore relie souvent une image concrète à une idée abstraite."); break;
            case 58: pair(out,"In an argument, premises are reasons offered to support the ___.", "conclusion","greeting","punctuation","speaker's age",0,"Les prémisses sont les raisons qui soutiennent la conclusion."); pair(out,"A strong critical analysis checks hidden assumptions and possible ___.", "counterexamples","font choices","greetings","page breaks",0,"Les contre-exemples peuvent révéler les limites d'un argument."); break;
            case 59: pair(out,"Which is most suitable for a formal report?", "We need to fix this soon.","The issue should be addressed promptly.","Fix it, okay?","Sort this thing out now.",1,"The issue should be addressed promptly convient mieux à un rapport formel."); pair(out,"When changing register, preserve the meaning while adapting tone and ___.", "word choice","the facts arbitrarily","the conclusion randomly","the topic completely",0,"Le registre adapte le vocabulaire et le ton au public et à la situation."); break;
            case 60: pair(out,"A precise complex argument should acknowledge a strong ___.", "counterargument","personal insult","unrelated anecdote","random slogan",0,"Reconnaître une objection sérieuse renforce l'analyse."); pair(out,"“This holds provided that…” introduces ___.", "a condition or limitation","a greeting","an absolute guarantee","a past habit",0,"Provided that indique une condition dont dépend la validité de l'affirmation."); break;
            default: break;
        }
    }

    private static void pair(List<Question> out, String q1, String a, String b, String c, String d, int correct1, String why1) {
        out.add(new Question(q1, new String[]{a,b,c,d}, correct1, why1));
        String q2 = "Which explanation best justifies the answer to: " + q1;
        String[] opts = new String[]{
                why1,
                "The answer is chosen without considering grammar or context.",
                "The sentence must be translated word for word.",
                "The rule is different in every sentence."
        };
        int correct2 = 0;
        String why2 = "Cette correction reprend la règle ou le sens précis évalué dans la première question.";
        out.add(new Question(q2, opts, correct2, why2));
    }
}
